from dataclasses import dataclass
from random import Random
from typing import Iterable

from examples.cpmp.instance import CPMPInstance


Move = tuple[int, int]


@dataclass(frozen=True)
class _Partial:
    state: tuple[tuple[int, ...], ...]
    path: tuple[Move, ...]


def _ordered_stack(st: tuple[int, ...]) -> bool:
    return all(st[i] >= st[i + 1] for i in range(len(st) - 1))


def _state_ordered(state: tuple[tuple[int, ...], ...]) -> bool:
    return all(_ordered_stack(s) for s in state)


def _misplaced_count(state: tuple[tuple[int, ...], ...]) -> int:
    count = 0
    for st in state:
        for i in range(len(st) - 1):
            if st[i] < st[i + 1]:
                count += 1
    return count


def _apply_move_state(
    state: tuple[tuple[int, ...], ...], move: Move
) -> tuple[tuple[int, ...], ...] | None:
    so, sd = move
    S = len(state)
    if not (0 <= so < S and 0 <= sd < S) or so == sd:
        return None
    if not state[so] or len(state[sd]) >= max(len(s) for s in state) + 10**9:
        return None
    stacks = [list(s) for s in state]
    c = stacks[so].pop()
    stacks[sd].append(c)
    return tuple(tuple(s) for s in stacks)


def empty_partial(inst: CPMPInstance):
    return _Partial(state=tuple(tuple(s) for s in inst.stacks), path=tuple())


def candidates(inst: CPMPInstance, partial) -> list:
    p = partial if isinstance(partial, _Partial) else _Partial(
        state=tuple(tuple(s) for s in partial[0]),
        path=tuple(partial[1]) if len(partial) > 1 else tuple(),
    )
    if _state_ordered(p.state):
        return []

    current_bad = _misplaced_count(p.state)
    cand: list[Move] = []

    for so in range(inst.S):
        if not p.state[so]:
            continue
        for sd in range(inst.S):
            if so == sd or len(p.state[sd]) >= inst.H:
                continue
            nxt = _apply_move_state(p.state, (so, sd))
            if nxt is None:
                continue
            # Solo permitimos movimientos que mejoren la situación local;
            # si no hay ninguno, complete_partial resolverá el callejón sin salida.
            if _misplaced_count(nxt) < current_bad:
                cand.append((so, sd))

    # Si no hay mejora estricta, permitimos movimientos "seguros" que no empeoran
    # el número de pilas desordenadas, para conservar decisiones reales.
    if not cand:
        for so in range(inst.S):
            if not p.state[so]:
                continue
            for sd in range(inst.S):
                if so == sd or len(p.state[sd]) >= inst.H:
                    continue
                nxt = _apply_move_state(p.state, (so, sd))
                if nxt is None:
                    continue
                if _misplaced_count(nxt) <= current_bad:
                    cand.append((so, sd))

    # Eliminar duplicados conservando orden.
    seen = set()
    out = []
    for m in cand:
        if m not in seen:
            seen.add(m)
            out.append(m)
    return out


def apply_action(inst: CPMPInstance, partial, action):
    p = partial if isinstance(partial, _Partial) else _Partial(
        state=tuple(tuple(s) for s in partial[0]),
        path=tuple(partial[1]) if len(partial) > 1 else tuple(),
    )
    so, sd = int(action[0]), int(action[1])
    nxt = _apply_move_state(p.state, (so, sd))
    if nxt is None:
        return p
    return _Partial(state=nxt, path=p.path + ((so, sd),))


def is_complete(inst: CPMPInstance, partial) -> bool:
    p = partial if isinstance(partial, _Partial) else _Partial(
        state=tuple(tuple(s) for s in partial[0]),
        path=tuple(partial[1]) if len(partial) > 1 else tuple(),
    )
    return _state_ordered(p.state)


def to_solution(inst: CPMPInstance, partial):
    p = partial if isinstance(partial, _Partial) else _Partial(
        state=tuple(tuple(s) for s in partial[0]),
        path=tuple(partial[1]) if len(partial) > 1 else tuple(),
    )
    return canonical(p.path)


def complete_partial(inst: CPMPInstance, partial, rng: Random):
    p = partial if isinstance(partial, _Partial) else _Partial(
        state=tuple(tuple(s) for s in partial[0]),
        path=tuple(partial[1]) if len(partial) > 1 else tuple(),
    )
    if _state_ordered(p.state):
        return canonical(p.path)

    # Resolver desde el estado actual usando la vista heurística aprobada.
    tmp = CPMPInstance(p.state, inst.H, name=inst.name)
    suffix = trivial_solution(tmp)
    return canonical(p.path + suffix)


def partial_lower_bound(inst: CPMPInstance, partial) -> float:
    p = partial if isinstance(partial, _Partial) else _Partial(
        state=tuple(tuple(s) for s in partial[0]),
        path=tuple(partial[1]) if len(partial) > 1 else tuple(),
    )
    # Cota inferior trivial: al menos 0 movimientos adicionales.
    return float(len(p.path))


def partial_key(inst: CPMPInstance, partial):
    p = partial if isinstance(partial, _Partial) else _Partial(
        state=tuple(tuple(s) for s in partial[0]),
        path=tuple(partial[1]) if len(partial) > 1 else tuple(),
    )
    return p.state


